 public static class LrcText {
  static readonly Regex Stamp=new Regex(@"\[(\d{1,3}):([0-5]\d)(?:[.:](\d{1,3}))?\]",RegexOptions.CultureInvariant);
  public static string SafeLine(string text){return new string((text??"").Where(c=>!Char.IsControl(c)||c=='\t').ToArray()).Replace('\t',' ').Trim();}
  public static List<LyricLine> Parse(string text){var result=new List<LyricLine>();if(String.IsNullOrEmpty(text))return result;if(text.Length>65536)throw new InvalidDataException("Lyrics too large");var rows=text.Replace("\r","").Split('\n');if(rows.Length>4096)throw new InvalidDataException("Too many lyric lines");int offset=0;foreach(var row in rows){var m=Regex.Match(row.Trim(),@"^\[offset:([+-]?\d{1,5})\]$",RegexOptions.IgnoreCase|RegexOptions.CultureInvariant);if(m.Success)offset=Int32.Parse(m.Groups[1].Value,CultureInfo.InvariantCulture);}
   foreach(var row in rows){var all=Stamp.Matches(row);if(all.Count==0||all[0].Index!=0)continue;var matches=new List<Match>();int end=0;foreach(Match match in all){if(match.Index!=end)break;matches.Add(match);end=match.Index+match.Length;}string body=SafeLine(row.Substring(end));if(body.Length>512)body=body.Substring(0,512);foreach(Match m in matches){double fraction=m.Groups[3].Success?Double.Parse("0."+m.Groups[3].Value,CultureInfo.InvariantCulture):0;double seconds=Int32.Parse(m.Groups[1].Value,CultureInfo.InvariantCulture)*60+Int32.Parse(m.Groups[2].Value,CultureInfo.InvariantCulture)+fraction+offset/1000d;if(seconds<0||seconds>86400)continue;result.Add(new LyricLine(seconds,body));if(result.Count>4096)throw new InvalidDataException("Too many timestamps");}}
   return result.OrderBy(l=>l.Seconds).ToList();
  }
  public static int Index(LyricDocument document,double? position){if(document==null||!position.HasValue||Double.IsNaN(position.Value)||Double.IsInfinity(position.Value)||position<0)return -1;int lo=0,hi=document.Lines.Count-1,found=-1;while(lo<=hi){int mid=(lo+hi)/2;if(document.Lines[mid].Seconds<=position){found=mid;lo=mid+1;}else hi=mid-1;}return found;}
  public static string Display(LyricResult result,double? position){if(result==null)return "\u6b4c\u8bcd\u670d\u52a1\u672a\u542f\u7528";if(result.State=="ready"||result.State=="plain"){
    var doc=result.Document;if(doc==null)return "\u6682\u65e0\u6b4c\u8bcd";if(position.HasValue&&doc.Lines.Count>0){int index=Index(doc,position);return index<0?"\u524d\u594f":String.IsNullOrWhiteSpace(doc.Lines[index].Text)?"\u95f4\u594f":doc.Lines[index].Text;}
    string first=doc.Lines.Select(l=>l.Text).FirstOrDefault(t=>!String.IsNullOrWhiteSpace(t));if(String.IsNullOrWhiteSpace(first))first=doc.Plain.Split('\n').Select(SafeLine).FirstOrDefault(t=>!String.IsNullOrWhiteSpace(t));return "\u672a\u540c\u6b65 \u00b7 "+(first??"\u5df2\u83b7\u53d6\u6b4c\u8bcd");
   }switch(result.State){case "loading":return "\u6b4c\u8bcd\u83b7\u53d6\u4e2d";case "instrumental":return "\u7eaf\u97f3\u4e50";case "ambiguous":return "\u6b4c\u8bcd\u7248\u672c\u672a\u786e\u8ba4";case "not-found":return "\u672a\u627e\u5230\u5339\u914d\u6b4c\u8bcd";case "rate-limited":return "\u6b4c\u8bcd\u670d\u52a1\u7a0d\u540e\u91cd\u8bd5";case "unavailable":return "\u6b4c\u8bcd\u6682\u4e0d\u53ef\u7528";case "no-track":return "\u7b49\u5f85\u6b4c\u66f2";default:return "\u6b4c\u8bcd\u670d\u52a1\u672a\u542f\u7528";}}
 }
 public static class LyricMatcher {
  public static string Normalize(string value){if(String.IsNullOrWhiteSpace(value))return "";return Regex.Replace(value.Normalize(NormalizationForm.FormKC).Trim(),@"\s+"," ").ToUpperInvariant();}
  public static bool Eligible(Snapshot s){return s!=null&&NeteaseSource.IsNetease(s.SourceId)&&!String.IsNullOrWhiteSpace(s.Title)&&!String.IsNullOrWhiteSpace(s.Artist)&&s.Title.Length<=200&&s.Artist.Length<=200&&!s.Title.Any(Char.IsControl)&&!s.Artist.Any(Char.IsControl);}
  public static string Key(Snapshot s){return !Eligible(s)?"":Normalize(s.Title)+"\n"+Normalize(s.Artist)+"\n"+(MusicTimeline.Duration(s).HasValue?MusicTimeline.Duration(s).Value.ToString("0.0",CultureInfo.InvariantCulture):"unknown")+"\n"+Normalize(s.Album);}
  static string Text(IDictionary<string,object> d,string key){object v;return d.TryGetValue(key,out v)?v as string:null;}
  static double? Number(IDictionary<string,object> d,string key){object v;if(!d.TryGetValue(key,out v)||v==null||v is bool)return null;try{double n=Convert.ToDouble(v,CultureInfo.InvariantCulture);return !Double.IsNaN(n)&&!Double.IsInfinity(n)?(double?)n:null;}catch{return null;}}
  static LyricResult ParseOne(IDictionary<string,object> item){string plain=Text(item,"plainLyrics")??"",synced=Text(item,"syncedLyrics")??"";if(plain.Length>65536||synced.Length>65536)throw new InvalidDataException("Lyrics too large");object instrumental;bool isInstrumental=item.TryGetValue("instrumental",out instrumental)&&instrumental is bool&&(bool)instrumental;if(isInstrumental)return plain.Length==0&&synced.Length==0?new LyricResult("instrumental"):new LyricResult("ambiguous");var lines=LrcText.Parse(synced);double total=Number(item,"duration").Value;if(lines.Any(l=>l.Seconds>total+3))return new LyricResult("not-found");if(lines.Count==0&&String.IsNullOrWhiteSpace(plain))return new LyricResult("not-found");return new LyricResult(lines.Count>0?"ready":"plain",new LyricDocument(plain,lines,total));}
  static string PlainKey(LyricDocument doc){return String.Join("\n",(String.IsNullOrWhiteSpace(doc.Plain)?doc.Lines.Select(l=>l.Text):doc.Plain.Replace("\r","").Split('\n').AsEnumerable()).Select(Normalize).Where(t=>t.Length>0));}
  static string TimedKey(LyricDocument doc){return String.Join("\n",doc.Lines.Select(l=>l.Seconds.ToString("0.000",CultureInfo.InvariantCulture)+":"+Normalize(l.Text)));}
  public static LyricResult Match(string json,Snapshot song){if(!Eligible(song))return new LyricResult("no-track");if(json==null||json.Length>1048576)throw new InvalidDataException("Lyrics response too large");var root=new JavaScriptSerializer{MaxJsonLength=1048576,RecursionLimit=12}.DeserializeObject(json) as IList;if(root==null||root.Count>20)throw new InvalidDataException("Invalid lyrics list");var matches=new List<IDictionary<string,object>>();var ids=new HashSet<double>();foreach(var row in root){var d=row as IDictionary<string,object>;if(d==null)continue;double? id=Number(d,"id"),duration=Number(d,"duration");if(!id.HasValue||id<=0||!duration.HasValue||duration<=0||duration>86400)continue;if(Normalize(Text(d,"trackName"))!=Normalize(song.Title)||Normalize(Text(d,"artistName"))!=Normalize(song.Artist))continue;if(MusicTimeline.Duration(song).HasValue&&Math.Abs(MusicTimeline.Duration(song).Value-duration.Value)>2)continue;if(!ids.Add(id.Value))return new LyricResult("ambiguous");matches.Add(d);}
   if(matches.Count==0)return new LyricResult("not-found");if(!String.IsNullOrWhiteSpace(song.Album)){var album=matches.Where(d=>Normalize(Text(d,"albumName"))==Normalize(song.Album)).ToList();if(album.Count>0)matches=album;}
   if(matches.Count==1)return ParseOne(matches[0]);if(!MusicTimeline.Duration(song).HasValue)return new LyricResult("ambiguous");var parsed=matches.Select(ParseOne).Where(r=>r.State!="not-found").ToList();if(parsed.Count==0)return new LyricResult("not-found");if(parsed.Any(r=>r.State=="ambiguous"))return new LyricResult("ambiguous");var timed=parsed.Where(r=>r.State=="ready").ToList();if(timed.Count>0){if(timed.Select(r=>TimedKey(r.Document)).Distinct(StringComparer.Ordinal).Count()!=1)return new LyricResult("ambiguous");string plain=PlainKey(timed[0].Document);if(parsed.Any(r=>r.State=="instrumental"||r.State=="plain"&&PlainKey(r.Document)!=plain))return new LyricResult("ambiguous");return timed[0];}
   if(parsed.All(r=>r.State=="instrumental"))return parsed[0];if(parsed.All(r=>r.State=="plain")&&parsed.Select(r=>PlainKey(r.Document)).Distinct(StringComparer.Ordinal).Count()==1)return parsed[0];return new LyricResult("ambiguous");
  }
 }
 public sealed class LyricHttpResult {public int Status;public string Body,RetryAfter;}
 public sealed class LrclibSource:IDisposable {
  sealed class Entry {public LyricResult Result;public DateTimeOffset Expires,Used;}
  readonly object cacheGate=new object();readonly Dictionary<string,Entry> cache=new Dictionary<string,Entry>();readonly SemaphoreSlim serial=new SemaphoreSlim(1,1);readonly CancellationTokenSource stopped=new CancellationTokenSource();readonly Func<Uri,CancellationToken,Task<LyricHttpResult>> transport;readonly Func<DateTimeOffset> now;DateTimeOffset nextRequest=DateTimeOffset.MinValue,blockedUntil=DateTimeOffset.MinValue;volatile bool disposed;
  readonly string backoffFile;public readonly bool Enabled;public int Requests {get;private set;}public int? LastResponseStatus {get;private set;}public DateTimeOffset? RetryNotBefore {get{return blockedUntil>now()?(DateTimeOffset?)blockedUntil:null;}}public int CacheCount {get{lock(cacheGate)return cache.Count;}}
  public LrclibSource(bool enabled,Func<Uri,CancellationToken,Task<LyricHttpResult>> transport=null,Func<DateTimeOffset> clock=null,string cooldownFile=null){Enabled=enabled;this.transport=transport??Fetch;now=clock??(()=>DateTimeOffset.UtcNow);backoffFile=cooldownFile;if(enabled&&backoffFile!=null)LoadBackoff();}
  static void PlainFile(string file){var p=Path.GetFullPath(file);while(!String.IsNullOrEmpty(p)){if((File.Exists(p)||Directory.Exists(p))&&(File.GetAttributes(p)&FileAttributes.ReparsePoint)!=0)throw new IOException("Redirected lyrics state rejected");var parent=Path.GetDirectoryName(p);if(parent==p)break;p=parent;}}
  void LoadBackoff(){try{PlainFile(backoffFile);if(!File.Exists(backoffFile))return;if(new FileInfo(backoffFile).Length>2048)throw new InvalidDataException();var d=new JavaScriptSerializer{MaxJsonLength=2048,RecursionLimit=4}.DeserializeObject(File.ReadAllText(backoffFile)) as IDictionary<string,object>;object host,until;DateTimeOffset expiry;if(d==null||!d.TryGetValue("host",out host)||!(host is string)||(string)host!="lrclib.net"||!d.TryGetValue("untilUtc",out until)||!(until is string)||!DateTimeOffset.TryParse((string)until,CultureInfo.InvariantCulture,DateTimeStyles.RoundtripKind,out expiry))throw new InvalidDataException();blockedUntil=expiry;}catch{blockedUntil=DateTimeOffset.MaxValue;}}
  void SaveBackoff(int status){if(backoffFile==null)return;try{PlainFile(backoffFile);Directory.CreateDirectory(Path.GetDirectoryName(backoffFile));string temp=backoffFile+"."+Guid.NewGuid().ToString("N")+".tmp";File.WriteAllText(temp,new JavaScriptSerializer().Serialize(new{schema=1,host="lrclib.net",untilUtc=blockedUntil.ToUniversalTime().ToString("o"),status=status}),new UTF8Encoding(false));if(File.Exists(backoffFile))File.Replace(temp,backoffFile,null);else File.Move(temp,backoffFile);}catch{blockedUntil=DateTimeOffset.MaxValue;}}
  public static string CooldownPath(string configuration){var state=new DirectoryInfo(Path.GetDirectoryName(Path.GetFullPath(configuration)));var release=state.Parent;var channel=release==null?null:release.Parent;var workspace=channel==null?null:channel.Parent;if(state.Name=="state"&&channel!=null&&(channel.Name=="staging"||channel.Name=="releases")&&workspace!=null&&File.Exists(Path.Combine(workspace.FullName,"Sidebar.exe"))&&Directory.Exists(Path.Combine(workspace.FullName,"sidebar-launcher")))return Path.Combine(workspace.FullName,"sidebar-launcher","lyrics-backoff.json");return Path.Combine(state.FullName,"lyrics-backoff.json");}
  public static LrclibSource FromApprovedConfiguration(string file){try{PlainFile(file);if(!File.Exists(file)||new FileInfo(file).Length>4096)return new LrclibSource(false);var d=new JavaScriptSerializer{MaxJsonLength=4096,RecursionLimit=4}.DeserializeObject(File.ReadAllText(file)) as IDictionary<string,object>;object service,enabled;if(d==null||!d.TryGetValue("service",out service)||!(service is string)||(string)service!="lrclib"||!d.TryGetValue("enabled",out enabled)||!(enabled is bool)||!(bool)enabled)return new LrclibSource(false);return new LrclibSource(true,null,null,CooldownPath(file));}catch{return new LrclibSource(false);}}
  public static Uri SearchUri(Snapshot song){if(!LyricMatcher.Eligible(song))throw new ArgumentException("Track identity unavailable");return new Uri("https://lrclib.net/api/search?track_name="+Uri.EscapeDataString(song.Title.Trim())+"&artist_name="+Uri.EscapeDataString(song.Artist.Trim()));}
  public static DateTimeOffset RetryDeadline(string value,DateTimeOffset when){long seconds;if(Int64.TryParse(value,NumberStyles.Integer,CultureInfo.InvariantCulture,out seconds)&&seconds>=0){try{return when.AddSeconds(Math.Max(1,seconds));}catch{return DateTimeOffset.MaxValue;}}DateTimeOffset date;if(DateTimeOffset.TryParse(value,CultureInfo.InvariantCulture,DateTimeStyles.AssumeUniversal,out date)&&date>when)return date;return when.AddMinutes(1);}
  static async Task<LyricHttpResult> Fetch(Uri uri,CancellationToken token){if(uri.Scheme!="https"||uri.Host!="lrclib.net"||uri.Port!=443||uri.AbsolutePath!="/api/search")throw new InvalidOperationException("Lyrics endpoint denied");var req=(HttpWebRequest)WebRequest.Create(uri);req.Method="GET";req.AllowAutoRedirect=false;req.Timeout=8000;req.ReadWriteTimeout=8000;req.Accept="application/json";req.UserAgent="PersonalSidebar/1.0 (anonymous desktop client)";req.UseDefaultCredentials=false;req.PreAuthenticate=false;req.Credentials=null;
   using(var timeout=CancellationTokenSource.CreateLinkedTokenSource(token)){timeout.CancelAfter(8000);using(timeout.Token.Register(()=>req.Abort())){HttpWebResponse response=null;try{response=(HttpWebResponse)await req.GetResponseAsync().ConfigureAwait(false);}catch(WebException e){response=e.Response as HttpWebResponse;if(response==null)throw;}using(response){int status=(int)response.StatusCode;if(status!=200)return new LyricHttpResult{Status=status,RetryAfter=response.Headers["Retry-After"]};if(response.ContentLength>1048576||response.ContentType==null||response.ContentType.IndexOf("json",StringComparison.OrdinalIgnoreCase)<0)throw new InvalidDataException("Lyrics response rejected");using(var input=response.GetResponseStream())using(var output=new MemoryStream()){var buffer=new byte[4096];int read;while((read=await input.ReadAsync(buffer,0,buffer.Length,timeout.Token).ConfigureAwait(false))>0){if(output.Length+read>1048576)throw new InvalidDataException("Lyrics response too large");output.Write(buffer,0,read);}return new LyricHttpResult{Status=status,Body=new UTF8Encoding(false,true).GetString(output.ToArray())};}}}}
  }
  void Remember(string key,LyricResult result){lock(cacheGate){if(disposed)return;if(cache.Count>=16&&!cache.ContainsKey(key)){string oldest=cache.OrderBy(p=>p.Value.Used).First().Key;cache.Remove(oldest);}cache[key]=new Entry{Result=result,Used=now(),Expires=result.State=="unavailable"?now().AddSeconds(60):now().AddMinutes(result.State=="ready"||result.State=="plain"||result.State=="instrumental"?360:15)};}}
  public async Task<LyricResult> ReadAsync(Snapshot song,CancellationToken token){if(!Enabled||disposed)return new LyricResult("disabled");if(song!=null)song=new Snapshot{SourceId=song.SourceId,Title=song.Title,Artist=song.Artist,Album=song.Album,DurationSeconds=song.DurationSeconds};string key=LyricMatcher.Key(song);if(key.Length==0)return new LyricResult("no-track");using(var cancel=CancellationTokenSource.CreateLinkedTokenSource(token,stopped.Token)){await serial.WaitAsync(cancel.Token).ConfigureAwait(false);try{if(disposed)return new LyricResult("disabled");lock(cacheGate){Entry item;if(cache.TryGetValue(key,out item)&&item.Expires>now()){item.Used=now();return item.Result;}}if(blockedUntil>now())return new LyricResult("rate-limited");var wait=nextRequest-now();if(wait>TimeSpan.Zero)await Task.Delay(wait,cancel.Token).ConfigureAwait(false);cancel.Token.ThrowIfCancellationRequested();Requests++;LyricResult result;try{var response=await transport(SearchUri(song),cancel.Token).ConfigureAwait(false);cancel.Token.ThrowIfCancellationRequested();LastResponseStatus=response.Status;if(response.Status==429||response.Status==503){var deadline=RetryDeadline(response.RetryAfter,now());blockedUntil=deadline>DateTimeOffset.MaxValue.AddMilliseconds(-250)?DateTimeOffset.MaxValue:deadline.AddMilliseconds(250);SaveBackoff(response.Status);return new LyricResult("rate-limited");}result=response.Status==200?LyricMatcher.Match(response.Body,song):response.Status==404?new LyricResult("not-found"):new LyricResult("unavailable");}catch(OperationCanceledException){throw;}catch{cancel.Token.ThrowIfCancellationRequested();result=new LyricResult("unavailable");}finally{nextRequest=now().AddMilliseconds(500);}Remember(key,result);return result;}finally{serial.Release();}}}
  public void Dispose(){if(disposed)return;disposed=true;stopped.Cancel();lock(cacheGate)cache.Clear();}
 }
